#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
set +x
unset TF_LOG TF_LOG_PROVIDER TF_LOG_PATH OCI_HOME_OVERRIDE
umask 077
TOTAL_STAGES=12
REPO_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
cd "$REPO_DIR"
mkdir -p .bootstrap/keys .bootstrap/root
chmod 700 .bootstrap .bootstrap/keys .bootstrap/root
ENV_FILE="$REPO_DIR/.bootstrap/wizard.env"
WORK_DIR="$REPO_DIR/.bootstrap/root"
# Helpers here belong to the procedure; the template library above is unchanged.
require_value() { [[ -n "${!1}" && "${!1}" != *$'\n'* ]] || { warn "Invalid $1"; exit 1; }; }
persist() { require_value "$1"; write_env "$1" "${!1}"; }
# Adapt template helpers to Environment secrets without changing their library.
gh() {
  if [[ "${1:-}" == secret && "${2:-}" == set ]]; then
    command gh "$@" --repo "$GITHUB_REPOSITORY" --env "$SECRET_ENVIRONMENT"
  elif [[ "${1:-}" == variable && "${2:-}" == set ]]; then
    command gh "$@" --repo "$GITHUB_REPOSITORY"
  else
    command gh "$@"
  fi
}
write_inputs() {
  export TENANCY_OCID HOME_REGION STATE_BUCKET STATE_NAMESPACE IAM_EXCLUSION_MODE REPO_DIR WORK_DIR
  python3 - <<'PY'
import json, os
from pathlib import Path
root = Path(os.environ['REPO_DIR'])
values = dict(tenancy_ocid=os.environ['TENANCY_OCID'], region=os.environ['HOME_REGION'],
              state_bucket_name=os.environ['STATE_BUCKET'], state_namespace=os.environ['STATE_NAMESPACE'],
              iam_exclusion_mode=os.environ['IAM_EXCLUSION_MODE'],
              pipeline_public_keys={r:(root / '.bootstrap/keys' / f'{r}.public.pem').read_text() for r in ('apply','plan')})
(Path(os.environ['WORK_DIR']) / 'owner.auto.tfvars.json').write_text(json.dumps(values, indent=2) + '\n')
PY
}
install_identity() {
  local role="$1" secret_env="$2" user fingerprint pem
  SECRET_ENVIRONMENT="$secret_env"
  if [[ "$role" == plan ]]; then user="$PLAN_USER_OCID"; fingerprint="$PLAN_FINGERPRINT"
  else user="$APPLY_USER_OCID"; fingerprint="$APPLY_FINGERPRINT"; fi
  pem=$(<"$REPO_DIR/.bootstrap/keys/$role.pem")
  set_secret OCI_TENANCY_OCID "$TENANCY_OCID"
  set_secret OCI_USER_OCID "$user"
  set_secret OCI_FINGERPRINT "$fingerprint"
  set_secret OCI_PRIVATE_KEY "$pem"
  set_secret OCI_REGION "$HOME_REGION"
  unset pem
  [[ ${#SKIPPED[@]} -eq 0 ]] || { warn "Secret installation incomplete; stop and resolve gh authentication."; exit 1; }
}

banner "OCI Bootstrap: owner setup"
stage "Tenancy and repository"
for binary in oci terraform openssl gh python3; do
  command -v "$binary" >/dev/null || { warn "Install $binary first."; exit 1; }
done
[[ $(terraform version -json | python3 -c 'import json,sys; print(json.load(sys.stdin)["terraform_version"])') == "$(cat .terraform-version)" ]] || { warn "Install the pinned Terraform version."; exit 1; }
open_url "https://cloud.oracle.com/tenancy"
step "Copy the tenancy OCID and home region from Tenancy details."
ask TENANCY_OCID "Tenancy OCID:"; persist TENANCY_OCID
ask HOME_REGION "Home region (for this Tenancy: us-ashburn-1):"; persist HOME_REGION
[[ "$TENANCY_OCID" == ocid1.tenancy.* && "$HOME_REGION" =~ ^[a-z0-9-]+$ ]] || exit 1
open_url "https://github.com/appiahco/terraform-oci-tenancy"
ask GITHUB_REPOSITORY "GitHub repository (owner/repo):"; persist GITHUB_REPOSITORY
[[ "$GITHUB_REPOSITORY" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]] || exit 1
ask OWNER_LOGIN "Owner's GitHub login (Foundation reviewer):"; persist OWNER_LOGIN
[[ "$OWNER_LOGIN" =~ ^[A-Za-z0-9-]+$ ]] || exit 1

stage "Short-lived owner session and MFA"
open_url "https://docs.oracle.com/en-us/iaas/Content/API/SDKDocs/clitoken.htm"
ask OWNER_PROFILE "New owner session profile name:"; persist OWNER_PROFILE
ask OWNER_CONFIG "OCI config path (must be $HOME/.oci/config for the pinned provider/backend):"; persist OWNER_CONFIG
[[ "$OWNER_CONFIG" == "$HOME/.oci/config" && "$OWNER_PROFILE" =~ ^[A-Za-z0-9_-]+$ ]] || exit 1
confirm "Authenticate your owner session now?" || exit 1
oci session authenticate --region "$HOME_REGION" --profile-name "$OWNER_PROFILE" --config-location "$OWNER_CONFIG"
export OCI_CONFIG_FILE="$OWNER_CONFIG" OCI_CONFIG_FILE_PROFILE="$OWNER_PROFILE" OCI_AUTH=SecurityToken OCI_REGION="$HOME_REGION"
export OCI_auth=SecurityToken OCI_config_file_profile="$OWNER_PROFILE" OCI_region="$HOME_REGION"
oci session validate --config-file "$OWNER_CONFIG" --profile "$OWNER_PROFILE" --auth security_token
open_url "https://docs.oracle.com/en-us/iaas/Content/Identity/Tasks/usingmfa.htm"
step "Complete owner MFA using the documented procedure for your identity type. Keep Break-glass and identity-domain policies unmanaged."
confirm "Owner MFA is enabled and Break-glass access is verified?" || exit 1

stage "Generate both pipeline API key pairs"
open_url "https://docs.oracle.com/en-us/iaas/Content/API/Concepts/apisigningkey.htm"
for role in apply plan; do
  private="$REPO_DIR/.bootstrap/keys/$role.pem"
  public="$REPO_DIR/.bootstrap/keys/$role.public.pem"
  if [[ ! -e "$private" && ! -e "$public" ]]; then
    confirm "Generate a new $role RSA key pair locally?" || exit 1
    openssl genrsa -out "$private" 2048
    openssl rsa -in "$private" -pubout -out "$public" 2>/dev/null
  fi
  [[ -f "$private" && -f "$public" ]] || { warn "Partial key pair; repair it without overwriting an installed key."; exit 1; }
  chmod 600 "$private" "$public"
  expected=$(openssl rsa -in "$private" -pubout 2>/dev/null)
  [[ "$expected" == "$(cat "$public")" ]] || { warn "Key pair mismatch."; exit 1; }
  fingerprint=$(openssl rsa -pubin -in "$public" -outform DER 2>/dev/null | openssl dgst -md5 -c | awk '{print $NF}')
  if [[ "$role" == apply ]]; then write_env APPLY_FINGERPRINT "$fingerprint"
  else write_env PLAN_FINGERPRINT "$fingerprint"; fi
  unset expected
  note "$role private PEM stays in .bootstrap/keys; only the public PEM enters Terraform."
done

stage "Review public Bootstrap inputs"
open_url "https://cloud.oracle.com/object-storage/buckets"
step "Obtain Object Storage namespace using the owner session (not a standing personal key)."
STATE_NAMESPACE=$(oci os ns get --config-file "$OWNER_CONFIG" --profile "$OWNER_PROFILE" --auth security_token --query data --raw-output)
persist STATE_NAMESPACE
ask STATE_BUCKET "New state bucket name (letters, digits, underscore, hyphen):"; persist STATE_BUCKET
[[ "$STATE_BUCKET" =~ ^[A-Za-z0-9_-]+$ ]] || exit 1
# Preserve the working mode, including an owner-applied fallback, on resume.
if [[ -f "$WORK_DIR/owner.auto.tfvars.json" ]]; then
  IAM_EXCLUSION_MODE=$(python3 - "$WORK_DIR/owner.auto.tfvars.json" <<'PYMODE'
import json,sys
print(json.load(open(sys.argv[1]))['iam_exclusion_mode'])
PYMODE
)
else
  IAM_EXCLUSION_MODE=$(_existing IAM_EXCLUSION_MODE || true)
  IAM_EXCLUSION_MODE=${IAM_EXCLUSION_MODE:-name_conditions}
fi
[[ "$IAM_EXCLUSION_MODE" == name_conditions || "$IAM_EXCLUSION_MODE" == deny ]] || exit 1
write_env IAM_EXCLUSION_MODE "$IAM_EXCLUSION_MODE"
for file in bootstrap/*.tf; do
  [[ "$file" == bootstrap/backend.tf ]] || cp "$file" "$WORK_DIR/"
done
cp bootstrap/.terraform.lock.hcl "$WORK_DIR/"
write_inputs
note "Review .bootstrap/root/owner.auto.tfvars.json: public PEMs and identifiers only."
pause "Review the inputs, then press Enter."

stage "Owner-reviewed manual Bootstrap apply"
if [[ -f "$WORK_DIR/backend.tf" ]]; then
  note "Remote backend already enabled: later Bootstrap changes follow the same manual path."
  terraform -chdir="$WORK_DIR" init -migrate-state -lockfile=readonly -backend-config="$REPO_DIR/.bootstrap/backend.hcl"
else
  note "First setup uses local state in .bootstrap/root; checked-in Bootstrap keeps its OCI backend."
  terraform -chdir="$WORK_DIR" init -input=false -lockfile=readonly
fi
terraform -chdir="$WORK_DIR" plan -input=false
confirm "Apply this reviewed Bootstrap configuration as the owner? Terraform will ask again." || exit 1
terraform -chdir="$WORK_DIR" apply -input=true
terraform -chdir="$WORK_DIR" output -json setup > "$REPO_DIR/.bootstrap/setup.json"
for field in compartment_ocid users.apply users.plan; do
  value=$(python3 - "$REPO_DIR/.bootstrap/setup.json" "$field" <<'PY'
import json,sys
value=json.load(open(sys.argv[1]))
for part in sys.argv[2].split('.'): value=value[part]
print(value)
PY
)
  case "$field" in compartment_ocid) write_env BOOTSTRAP_COMPARTMENT_OCID "$value";; users.apply) write_env APPLY_USER_OCID "$value";; users.plan) write_env PLAN_USER_OCID "$value";; esac
done

stage "Verify permissions and record real evidence"
python3 - <<'PYCONFIG'
import configparser, json
from pathlib import Path
setup=json.loads(Path('.bootstrap/setup.json').read_text())
inputs=json.loads(Path('.bootstrap/root/owner.auto.tfvars.json').read_text())
config=configparser.ConfigParser()
for role in ('apply','plan'):
    config[role]={'tenancy':inputs['tenancy_ocid'], 'region':inputs['region'],
                  'user':setup['users'][role], 'fingerprint':setup['fingerprints'][role],
                  'key_file':str(Path(f'.bootstrap/keys/{role}.pem').resolve())}
with Path('.bootstrap/pipeline.config').open('w') as stream: config.write(stream)
PYCONFIG
open_url "https://docs.oracle.com/en-us/iaas/Content/Identity/policysyntax/conditions.htm"
step "Follow bootstrap/README.md permission probes using each pipeline identity. Record results outside secrets and logs."
step "Prove both pipeline groups and policies reject changes, ordinary resources remain manageable, and only state objects are writable inside Bootstrap."
step "If name exclusions fail: STOP. Enable OCI IAM Deny as the default administrator, select deny mode in the public tfvars, manually plan/apply, then repeat all probes."
open_url "https://docs.oracle.com/en-us/iaas/Content/Identity/policysyntax/denypolicies.htm"
ask IAM_EXCLUSION_MODE "Verified exclusion mode (name_conditions or deny):"
[[ "$IAM_EXCLUSION_MODE" == name_conditions || "$IAM_EXCLUSION_MODE" == deny ]] || exit 1
current_mode=$(python3 - "$WORK_DIR/owner.auto.tfvars.json" <<'PY'
import json,sys
print(json.load(open(sys.argv[1]))['iam_exclusion_mode'])
PY
)
[[ "$IAM_EXCLUSION_MODE" == "$current_mode" ]] || { warn "Apply the selected mode and repeat probes before continuing."; exit 1; }
persist IAM_EXCLUSION_MODE
confirm "Real IAM exclusion evidence and pipeline permissions are verified and recorded?" || exit 1

stage "Enable and migrate native OCI state"
open_url "https://developer.hashicorp.com/terraform/language/backend/oci"
export STATE_BUCKET STATE_NAMESPACE
python3 - <<'PY'
import json,os
from pathlib import Path
Path('.bootstrap/backend.hcl').write_text('bucket = '+json.dumps(os.environ['STATE_BUCKET'])+'\nnamespace = '+json.dumps(os.environ['STATE_NAMESPACE'])+'\n')
PY
if [[ ! -f "$WORK_DIR/backend.tf" ]]; then
  confirm "Enable OCI backend and migrate local Bootstrap state?" || exit 1
  cp bootstrap/backend.tf "$WORK_DIR/"
fi
# Re-running resumes an interrupted migration. No -force-copy or -reconfigure.
terraform -chdir="$WORK_DIR" init -migrate-state -lockfile=readonly -backend-config="$REPO_DIR/.bootstrap/backend.hcl"
note "Native OCI conditional writes and .lock objects provide locking. Other Roots have their own fixed keys."

stage "No-change plan before local-state deletion"
confirm "Run the remote no-change plan before deleting any local state?" || exit 1
rc=0
terraform -chdir="$WORK_DIR" plan -input=false -detailed-exitcode || rc=$?
[[ "$rc" -eq 0 ]] || { warn "Remote plan failed or has changes. Keep local state; resolve and re-run."; exit 1; }
oci os object head --namespace-name "$STATE_NAMESPACE" --bucket-name "$STATE_BUCKET" --name bootstrap/terraform.tfstate --config-file "$OWNER_CONFIG" --profile "$OWNER_PROFILE" --auth security_token >/dev/null
confirm "Remote state exists and plan has no changes. Delete local terraform.tfstate and its backups?" || exit 1
rm -f -- "$WORK_DIR/terraform.tfstate" "$WORK_DIR"/terraform.tfstate.backup
note "Keep .terraform backend metadata. Bucket versioning retains recovery copies."

stage "GitHub branch protection and Environments"
open_url "https://github.com/$GITHUB_REPOSITORY/settings/branches"
step "Use bootstrap/README.md GitHub settings instructions: protect main with strict checks terraform fmt, terraform validate, tflint."
open_url "https://github.com/$GITHUB_REPOSITORY/settings/environments"
step "Create plan without reviewers; apply-foundation with $OWNER_LOGIN as required reviewer; apply-workloads without reviewer."
step "Both apply Environments: Selected branches and tags → add branch main only; no tag rules. See linked GitHub documentation in the runbook."
confirm "Protection and all three Environments match the checklist?" || exit 1

stage "Install Environment credentials and backend variables"
open_url "https://github.com/$GITHUB_REPOSITORY/settings/environments"
confirm "Install Plan credentials in plan and Apply credentials in both apply Environments?" || exit 1
install_identity plan plan
install_identity apply apply-foundation
install_identity apply apply-workloads
set_var TF_STATE_BUCKET "$STATE_BUCKET"
set_var TF_STATE_NAMESPACE "$STATE_NAMESPACE"
[[ ${#SKIPPED[@]} -eq 0 ]] || { warn "Backend variable installation incomplete."; exit 1; }

stage "First green PR plan"
open_url "https://github.com/$GITHUB_REPOSITORY/pulls"
step "Open an in-repository PR changing a Root, or re-run an existing Root PR. Static gates and each affected Root plan must pass."
step "Bootstrap state must already be migrated. Foundation and Workloads init must not depend on Foundation outputs before its first apply."
ask FIRST_PLAN_PR_URL "Verified PR URL:"; persist FIRST_PLAN_PR_URL
open_url "$FIRST_PLAN_PR_URL"
ask FIRST_PLAN_RUN_URL "Green Actions run URL:"; persist FIRST_PLAN_RUN_URL
confirm "First PR plan is green and recorded in the owner checklist?" || exit 1

stage "Separate 90-day rotation reminders"
open_url "https://github.com/$GITHUB_REPOSITORY/actions/workflows/key-rotation.yml"
step "Enter each key's installation/rotation date (UTC YYYY-MM-DD). Daily workflow creates a separate issue when that key reaches 90 days."
ask OCI_APPLY_ROTATED_ON "Apply key installation date:"; persist OCI_APPLY_ROTATED_ON
ask OCI_PLAN_ROTATED_ON "Plan key installation date:"; persist OCI_PLAN_ROTATED_ON
python3 - "$OCI_APPLY_ROTATED_ON" "$OCI_PLAN_ROTATED_ON" <<'PY'
from datetime import date, datetime, timezone
import sys
for value in sys.argv[1:]:
    assert date.fromisoformat(value).isoformat() == value and date.fromisoformat(value) <= datetime.now(timezone.utc).date(), 'Invalid rotation date'
PY
confirm "Set each rotation baseline repository variable?" || exit 1
set_var OCI_APPLY_ROTATED_ON "$OCI_APPLY_ROTATED_ON"
set_var OCI_PLAN_ROTATED_ON "$OCI_PLAN_ROTATED_ON"
[[ ${#SKIPPED[@]} -eq 0 ]] || exit 1
note "For rotation: generate a new pair, update public input, owner-apply Bootstrap, update that identity's Environment secrets, then advance its date."
note "Record all owner checklist evidence in #24. Script completion alone does not complete the ticket."
finish
}

run_wizard "$@"; exit
